"""Own conservative spatial decoder for our 14-class pilot detector.
No community OCR implementation, coordinate labels, priors or symbol repair.
"""
import math,re,statistics
def iou(a,b):
    x=max(0,min(a[2],b[2])-max(a[0],b[0]));y=max(0,min(a[3],b[3])-max(a[1],b[1]))
    area=x*y;den=(a[2]-a[0])*(a[3]-a[1])+(b[2]-b[0])*(b[3]-b[1])-area
    return area/den if den>0 else 0
def decode(detections):
    chars=[]
    for item in sorted(detections,key=lambda x:-x['score']):
        if item['score']<.25:continue
        box=item['xyxy']
        if len(box)!=4 or not all(math.isfinite(x) for x in box) or box[2]<=box[0] or box[3]<=box[1]:
            return {'selected':None,'reason':'invalid-box','chunks':[]}
        duplicate=False
        for old in chars:
            if iou(box,old['xyxy'])>.45:
                if item['char']!=old['char']:return {'selected':None,'reason':'conflicting-character-boxes','chunks':[]}
                duplicate=True;break
        if not duplicate:chars.append(item)
    chars.sort(key=lambda x:(x['xyxy'][0]+x['xyxy'][2])/2)
    widths=[c['xyxy'][2]-c['xyxy'][0] for c in chars if c['char'].isdigit()]
    if not widths:return {'selected':None,'reason':'no-digits','chunks':[]}
    threshold=max(12.,.75*statistics.median(widths));groups=[]
    for item in chars:
        if not groups or item['xyxy'][0]-groups[-1][-1]['xyxy'][2]>threshold:groups.append([])
        groups[-1].append(item)
    chunks=[''.join(c['char'] for c in group) for group in groups];matches=[]
    for group,text in zip(groups,chunks):
        if not re.fullmatch(r'[+-]?\d+,[+-]?\d+,[+-]?\d+',text):continue
        xyz=list(map(int,text.split(',')))
        if not all(-2147483648<=x<=2147483647 for x in xyz):continue
        matches.append({'xyz':xyz,'score':min(c['score'] for c in group),'text':text})
    if len(matches)!=1:return {'selected':None,'reason':'no-unique-complete-triple','chunks':chunks}
    return {'selected':matches[0],'reason':'observed-complete-triple','chunks':chunks}

