import unittest
from coordinate_decode import decode
def line(text,start=0):
    boxes=[];x=start
    for c in text:
        if c==' ':x+=30;continue
        boxes.append({'char':c,'score':.95,'xyxy':[x,4,x+20,38]});x+=24
    return boxes
class DecoderTests(unittest.TestCase):
    def test_date_separate_without_editing_characters(self):
        self.assertEqual(decode(line('-557,-37,-25 2026-10-14 14:10:21+8'))['selected']['xyz'],[-557,-37,-25])
    def test_explicit_plus_and_zero(self):
        self.assertEqual(decode(line('+12,0,-3'))['selected']['xyz'],[12,0,-3])
    def test_missing_comma_rejected(self):self.assertIsNone(decode(line('-557-37,-25'))['selected'])
    def test_glued_date_rejected(self):self.assertIsNone(decode(line('-557,-37,-252026-10-14'))['selected'])
    def test_multiple_triplets_rejected(self):self.assertIsNone(decode(line('1,2,3 4,5,6'))['selected'])
    def test_conflicting_character_boxes_rejected(self):
        boxes=line('1,2,3');boxes.append({**boxes[0],'char':'7'})
        self.assertIsNone(decode(boxes)['selected'])
    def test_empty_and_overflow_rejected(self):
        self.assertIsNone(decode([])['selected']);self.assertIsNone(decode(line('2147483648,1,2'))['selected'])
    def test_low_confidence_does_not_invent_character(self):
        boxes=line('1,2,3');boxes[1]['score']=.1
        self.assertIsNone(decode(boxes)['selected'])
if __name__=='__main__':unittest.main()

