"""Separate truth-based scoring after own-model label-blind inference."""
from pathlib import Path
from collections import Counter
import json,sys
from coordinate_decode import iou
ROOT=Path(__file__).resolve().parent;V3=ROOT.parent/'coordinate-finetune-20261015/paired-v3'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
epochs=int(sys.argv[1]);pred=read(ROOT/f'evaluation-{epochs}e.json');manifest=read(ROOT/'pilot-v2/pilot-manifest.json')
own={r['id']:r for r in manifest['rows'] if r['kind']=='annotated-text'}
dev={f['id']:f for f in read(V3/'development-corpus.json')['frames']};fit={f['id']:f for f in read(V3/'training-pair-corpus.json')['frames']};truth={**dev,**fit}
scenes={r['id']:r['sceneGroup'] for r in read(V3/'paired-manifest.json')['rows']}
assert not set(own)&set(dev) and set(own)==set(fit)
groups={};wrong=[];fit_char_gt=Counter();fit_char_matches=Counter();judgments=[]
for row in pred['results']:
    fid=row['sourceId'];f=truth[fid];s=row['decode']['selected'];xyz=s['xyz'] if s else None
    if f['state']=='present':outcome='miss' if xyz is None else 'correct' if xyz==[f['expected'][k] for k in 'xyz'] else 'wrong'
    elif f['state']=='absent':outcome='trueNegative' if xyz is None else 'falsePositive'
    else:outcome='unknownNoReturn' if xyz is None else 'unknownReturned'
    memberships=['trained-fit-only'] if fid in fit else ['all-development']
    if fid in dev and fid in scenes:memberships.append(scenes[fid])
    if fid in dev and 776<=int(fid[-6:])<=787:memberships.append('heldout-stationary-776-787')
    for group in memberships:
        c=groups.setdefault(group,Counter());c['frames']+=1;c[outcome]+=1
    judgments.append({'id':fid,'trainedFitOnly':fid in fit,'state':f['state'],'expected':f['expected'],'outcome':outcome,'decoded':row['decode']})
    if outcome in ['wrong','falsePositive']:wrong.append(judgments[-1])
    if fid in own:
        used=set()
        for obj in own[fid]['objects']:
            fit_char_gt[obj['char']]+=1
            candidates=[(iou(obj['xyxy'],d['xyxy']),i) for i,d in enumerate(row['detections']) if i not in used and d['char']==obj['char']]
            if candidates:
                overlap,index=max(candidates)
                if overlap>=.5:used.add(index);fit_char_matches[obj['char']]+=1
summary=[{'group':g,**{k:c[k] for k in ['frames','correct','wrong','miss','falsePositive','trueNegative','unknownReturned','unknownNoReturn']}} for g,c in groups.items()]
assert next(r for r in summary if r['group']=='all-development')['frames']==319
report={'scope':'Own small-label YOLO pilot. 27 fit-only training sources,170 same-session development XYZ,141 absent,8 unknown; not independent acceptance. Fixed final epoch, fixed detector threshold and own decoder.',
    'epochs':epochs,'summary':summary,'wrongCases':wrong,'judgments':judgments,'fitCharactersAtIoU50AndConf25':{c:{'groundTruth':fit_char_gt[c],'matched':fit_char_matches[c]} for c in manifest['classes']},
    'sourceInference':str(ROOT/f'evaluation-{epochs}e.json'),'newTrainingImagePositions':2,'thirdPartyGameWeightsOrPseudoLabelsUsed':False,'productionChanged':False}
out=ROOT/f'report-{epochs}e.json';assert not out.exists();out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
for row in summary:
    if row['group'] in ['all-development','trained-fit-only','heldout-stationary-776-787','snow-pale-mixed']:print(row)
print('Fit character recall:',report['fitCharactersAtIoU50AndConf25'])
